 public void render(Path root,Response in,Traceability trace)throws IOException{
  SpringGenerationModel model=new SpringGenerationModel(in.profileSnapshot().path("profile"),in.tables());JsonNode p=model.profile();String base=p.path("basePackage").asText(),artifact=p.path("artifactId").asText(),app=javaName(artifact)+"Application",pkg="src/main/java/"+base.replace('.','/');
  put(root,"pom.xml",pom(p)
    .replace("<dependencies>","<dependencies><dependency><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-flyway</artifactId></dependency>")
    .replace("<testcontainers.version>2.0.3</testcontainers.version>","")
    .replace("<dependency><groupId>org.testcontainers</groupId><artifactId>testcontainers-postgresql</artifactId><version>$"+"{testcontainers.version}</version><scope>test</scope></dependency>",""));
  copyWrapper(root);
  put(root,pkg+"/"+app+".java","package "+base+";\nimport org.springframework.boot.SpringApplication;import org.springframework.boot.autoconfigure.SpringBootApplication;@SpringBootApplication public class "+app+"{public static void main(String[]a){SpringApplication.run("+app+".class,a);}}\n");
  put(root,pkg+"/exception/ResourceNotFoundException.java","package "+base+".exception;public class ResourceNotFoundException extends RuntimeException{public ResourceNotFoundException(String m){super(m);}}\n");
  put(root,pkg+"/exception/GlobalExceptionHandler.java",handler(base));
  for(Table t:model.generatedEntities())renderTable(root,pkg,base,model,t);
  put(root,"src/main/resources/application.yml",applicationYaml());
  put(root,"src/main/resources/db/migration/V1__create_schema.sql",authSchema()+schema(model.tables()));
  put(root,"src/main/java/"+base.replace('.','/')+"/auth/User.java",generatedAuthEntity(base));
  put(root,"src/main/java/"+base.replace('.','/')+"/auth/UserRepository.java",generatedUserRepository(base));
  put(root,"src/main/java/"+base.replace('.','/')+"/auth/RegisterRequest.java",generatedRegisterRequest(base));
  put(root,"src/main/java/"+base.replace('.','/')+"/auth/LoginRequest.java",generatedLoginRequest(base));
  put(root,"src/main/java/"+base.replace('.','/')+"/auth/AuthResponse.java",generatedAuthResponse(base));
  put(root,"src/main/java/"+base.replace('.','/')+"/auth/AuthService.java",generatedAuthService(base));
  put(root,"src/main/java/"+base.replace('.','/')+"/auth/AuthController.java",generatedAuthController(base));
  put(root,"src/main/java/"+base.replace('.','/')+"/auth/SecurityConfig.java",generatedSecurityConfig(base));
  put(root,"src/test/java/"+base.replace('.','/')+"/ApplicationContextTest.java",contextTest(base));
  String database=databaseName(artifact),databaseUser=database+"_user",databasePassword=developmentPassword(artifact);
  put(root,".env",devEnvironment(database,databaseUser,databasePassword));
  put(root,".env.example",exampleEnvironment(database,databaseUser));
  put(root,".gitignore",".env\ntarget/\n*.log\n.idea/\n.vscode/\n");
  put(root,"run.ps1",runPowerShell());put(root,"run.sh",runShell());
  put(root,"Dockerfile",dockerfile(p.path("javaVersion").asInt()));
  put(root,"docker-compose.yml",compose());
  put(root,"README.md",readme(artifact,database,trace));
  put(root,"postman/"+artifact+".postman_collection.json",postman(artifact,model.generatedEntities()));
 }
 private void renderTable(Path root,String pkg,String b,SpringGenerationModel model,Table t)throws IOException{String n=javaName(t.name()),r=t.name().replace('_','-');if(hasCompositeId(t))put(root,pkg+"/entity/"+n+"Id.java",embeddedId(b,n,t));put(root,pkg+"/entity/"+n+".java",entity(b,n,model,t));put(root,pkg+"/dto/"+n+"Request.java",request(b,n,t));put(root,pkg+"/dto/"+n+"Response.java",response(b,n,t));put(root,pkg+"/repository/"+n+"Repository.java",repository(b,n,t));put(root,pkg+"/mapper/"+n+"Mapper.java",mapper(b,n,t));put(root,pkg+"/service/"+n+"Service.java",service(b,n,t));put(root,pkg+"/controller/"+n+"Controller.java",controller(b,n,r,t));}
 private String entity(String b,String n,SpringGenerationModel model,Table t){Set<String>pk=new LinkedHashSet<>(t.primaryKey().columns());boolean composite=hasCompositeId(t);StringBuilder s=new StringBuilder("package "+b+".entity;\nimport jakarta.persistence.*;import java.util.*;@Entity @Table(name=\"").append(t.name()).append("\")public class ").append(n).append("{public ").append(n).append("(){}\n");if(composite)s.append("@EmbeddedId private ").append(n).append("Id id=new ").append(n).append("Id();\n");for(Column c:t.columns()){if(composite&&pk.contains(c.name()))continue;if(pk.contains(c.name()))s.append("@Id ");s.append("@Column(name=\"").append(c.name()).append("\",nullable=").append(c.nullable()).append(columnOptions(c.sqlType())).append(")private ").append(javaType(c.sqlType())).append(' ').append(field(c.name())).append(";\n");}int relationIndex=0;for(ForeignKey fk:t.foreignKeys()){if(fk.columns().size()!=1)continue;String column=fk.columns().getFirst().column(),target=javaName(fk.referencedTable()),relation=field(fk.referencedTable())+(++relationIndex);boolean nullable=t.columns().stream().filter(c->c.name().equals(column)).findFirst().orElseThrow().nullable(),unique=t.uniqueConstraints().stream().anyMatch(k->k.columns().equals(fk.columns().stream().map(ColumnPair::column).toList()));s.append(unique?"@OneToOne":"@ManyToOne").append("(fetch=FetchType.LAZY,optional=").append(nullable).append(")@JoinColumn(name=\"").append(column).append("\",insertable=false,updatable=false,nullable=").append(nullable).append(")private ").append(target).append(' ').append(relation).append(";\n");}for(SpringGenerationModel.ManyToMany relation:model.relationshipsFor(t.name()))appendManyToMany(s,t.name(),relation);if(composite)s.append("public ").append(n).append("Id getId(){return id;}public void setId(").append(n).append("Id id){this.id=id;}\n");for(Column c:t.columns()){String f=field(c.name()),cap=cap(f),jt=javaType(c.sqlType());if(composite&&pk.contains(c.name()))s.append("public ").append(jt).append(" get").append(cap).append("(){return id==null?null:id.get").append(cap).append("();}public void set").append(cap).append('(').append(jt).append(' ').append(f).append("){if(id==null)id=new ").append(n).append("Id();id.set").append(cap).append('(').append(f).append(");}\n");else s.append("public ").append(jt).append(" get").append(cap).append("(){return ").append(f).append(";}public void set").append(cap).append('(').append(jt).append(' ').append(f).append("){this.").append(f).append('=').append(f).append(";}\n");}return s.append("}\n").toString();}
 private String embeddedId(String b,String n,Table t){StringBuilder s=new StringBuilder("package "+b+".entity;\nimport jakarta.persistence.*;import java.io.Serializable;import java.util.Objects;@Embeddable public class ").append(n).append("Id implements Serializable{public ").append(n).append("Id(){}\n");for(String name:t.primaryKey().columns()){Column c=column(t,name);s.append("@Column(name=\"").append(c.name()).append("\",nullable=false").append(columnOptions(c.sqlType())).append(")private ").append(javaType(c.sqlType())).append(' ').append(field(c.name())).append(";\n");}for(String name:t.primaryKey().columns()){Column c=column(t,name);String f=field(c.name()),cap=cap(f),type=javaType(c.sqlType());s.append("public ").append(type).append(" get").append(cap).append("(){return ").append(f).append(";}public void set").append(cap).append('(').append(type).append(' ').append(f).append("){this.").append(f).append('=').append(f).append(";}\n");}String fields=String.join(",",t.primaryKey().columns().stream().map(this::field).toList());String equality=t.primaryKey().columns().stream().map(name->"Objects.equals("+field(name)+",value."+field(name)+")").collect(java.util.stream.Collectors.joining("&&"));return s.append("@Override public boolean equals(Object other){if(this==other)return true;if(!(other instanceof ").append(n).append("Id value))return false;return ").append(equality).append(";}@Override public int hashCode(){return Objects.hash(").append(fields).append(");}}\n").toString();}
 private void appendManyToMany(StringBuilder s,String table,SpringGenerationModel.ManyToMany relation){boolean owner=relation.ownerTable().equals(table);if(owner){s.append("@ManyToMany @JoinTable(name=\"").append(relation.joinTable().name()).append("\",").append(joinColumns("joinColumns",relation.ownerForeignKey())).append(',').append(joinColumns("inverseJoinColumns",relation.inverseForeignKey())).append(")private Set<").append(javaName(relation.inverseTable())).append("> ").append(relation.ownerField()).append("=new LinkedHashSet<>();\n");appendCollectionAccessors(s,javaName(relation.inverseTable()),relation.ownerField());}if(relation.inverseTable().equals(table)){s.append("@ManyToMany(mappedBy=\"").append(relation.ownerField()).append("\")private Set<").append(javaName(relation.ownerTable())).append("> ").append(relation.inverseField()).append("=new LinkedHashSet<>();\n");appendCollectionAccessors(s,javaName(relation.ownerTable()),relation.inverseField());}}
 private String joinColumns(String attribute,ForeignKey foreignKey){List<String>annotations=foreignKey.columns().stream().map(pair->"@JoinColumn(name=\""+pair.column()+"\",referencedColumnName=\""+pair.referencedColumn()+"\")").toList();return attribute+"="+(annotations.size()==1?annotations.getFirst():"{"+String.join(",",annotations)+"}");}
 private void appendCollectionAccessors(StringBuilder s,String target,String name){String cap=cap(name);s.append("public Set<").append(target).append("> get").append(cap).append("(){return ").append(name).append(";}public void set").append(cap).append("(Set<").append(target).append("> ").append(name).append("){this.").append(name).append('=').append(name).append(";}\n");}
 private String request(String b,String n,Table t){return "package "+b+".dto;import jakarta.validation.constraints.*;public record "+n+"Request("+params(t,true)+"){}\n";}private String response(String b,String n,Table t){return "package "+b+".dto;public record "+n+"Response("+params(t,false)+"){}\n";}private String params(Table t,boolean v){List<String>x=new ArrayList<>();for(Column c:t.columns())x.add((v&&!c.nullable()?"@NotNull ":"")+javaType(c.sqlType())+" "+field(c.name()));return String.join(",",x);}
 private String repository(String b,String n,Table t){return "package "+b+".repository;import "+b+".entity.*;import org.springframework.data.jpa.repository.JpaRepository;public interface "+n+"Repository extends JpaRepository<"+n+","+idType(t)+">{}\n";}
 private String mapper(String b,String n,Table t){StringBuilder set=new StringBuilder(),args=new StringBuilder();for(Column c:t.columns()){String cap=cap(field(c.name()));set.append("e.set").append(cap).append("(r.").append(field(c.name())).append("());");if(!args.isEmpty())args.append(',');args.append("e.get").append(cap).append("()");}return "package "+b+".mapper;import "+b+".entity."+n+";import "+b+".dto.*;import org.springframework.stereotype.Component;@Component public class "+n+"Mapper{public "+n+" toEntity("+n+"Request r){var e=new "+n+"();"+set+"return e;}public void update("+n+" e,"+n+"Request r){"+set+"}public "+n+"Response response("+n+" e){return new "+n+"Response("+args+");}}\n";}
 private String service(String b,String n,Table t){String idt=idType(t);return "package "+b+".service;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import "+b+".entity.*;import "+b+".dto.*;import "+b+".repository.*;import "+b+".mapper.*;import "+b+".exception.*;@Service public class "+n+"Service{private final "+n+"Repository repository;private final "+n+"Mapper mapper;public "+n+"Service("+n+"Repository r,"+n+"Mapper m){repository=r;mapper=m;}@Transactional public "+n+"Response create("+n+"Request r){return mapper.response(repository.save(mapper.toEntity(r)));}@Transactional(readOnly=true)public List<"+n+"Response> list(){return repository.findAll().stream().map(mapper::response).toList();}@Transactional(readOnly=true)public "+n+"Response get("+idt+" id){return mapper.response(repository.findById(id).orElseThrow(()->new ResourceNotFoundException(\""+n+" not found\")));}@Transactional public "+n+"Response update("+idt+" id,"+n+"Request r){var e=repository.findById(id).orElseThrow(()->new ResourceNotFoundException(\""+n+" not found\"));mapper.update(e,r);return mapper.response(repository.save(e));}@Transactional public void delete("+idt+" id){if(!repository.existsById(id))throw new ResourceNotFoundException(\""+n+" not found\");repository.deleteById(id);}}\n";}
 private String controller(String b,String n,String r,Table t){String idt=idType(t);return "package "+b+".controller;import java.util.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import "+b+".entity.*;import "+b+".dto.*;import "+b+".service.*;@RestController @RequestMapping(\"/api/"+r+"\")public class "+n+"Controller{private final "+n+"Service service;public "+n+"Controller("+n+"Service s){service=s;}@PostMapping public ResponseEntity<"+n+"Response> create(@Valid @RequestBody "+n+"Request r){return ResponseEntity.status(201).body(service.create(r));}@GetMapping public List<"+n+"Response> list(){return service.list();}@GetMapping(\"/{id}\")public "+n+"Response get(@PathVariable "+idt+" id){return service.get(id);}@PutMapping(\"/{id}\")public "+n+"Response update(@PathVariable "+idt+" id,@Valid @RequestBody "+n+"Request r){return service.update(id,r);}@DeleteMapping(\"/{id}\")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable "+idt+" id){service.delete(id);}}\n";}
 private String schema(List<Table>ts){StringBuilder s=new StringBuilder();for(Table t:ts){s.append("CREATE TABLE ").append(t.name()).append(" (\n");List<String>x=new ArrayList<>();for(Column c:t.columns())x.add("  "+c.name()+" "+c.sqlType()+(c.nullable()?"":" NOT NULL"));x.add("  CONSTRAINT "+t.primaryKey().name()+" PRIMARY KEY ("+String.join(",",t.primaryKey().columns())+")");for(Key u:t.uniqueConstraints())x.add("  CONSTRAINT "+u.name()+" UNIQUE ("+String.join(",",u.columns())+")");for(Check c:t.checks())x.add("  CONSTRAINT "+c.name()+" CHECK ("+c.expression()+")");s.append(String.join(",\n",x)).append("\n);\n");}for(Table t:ts)for(ForeignKey f:t.foreignKeys())s.append("ALTER TABLE ").append(t.name()).append(" ADD CONSTRAINT ").append(f.name()).append(" FOREIGN KEY (").append(pairs(f,true)).append(") REFERENCES ").append(f.referencedTable()).append(" (").append(pairs(f,false)).append(") ON DELETE ").append(f.onDelete()).append(";\n");return s.toString();}private String pairs(ForeignKey f,boolean a){return String.join(",",f.columns().stream().map(p->a?p.column():p.referencedColumn()).toList());}
  private String generatedAuthEntity(String b){return "package "+b+".auth; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; @Entity @Table(name=\"app_users\") public class User { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false,unique=true,length=254) private String email; @Column(name=\"password_hash\",nullable=false,length=100) private String passwordHash; @Column(name=\"display_name\",nullable=false,length=120) private String displayName; @Column(name=\"created_at\",nullable=false) private Instant createdAt=Instant.now(); public UUID getId(){return id;} public String getEmail(){return email;} public void setEmail(String email){this.email=email;} public String getPasswordHash(){return passwordHash;} public void setPasswordHash(String passwordHash){this.passwordHash=passwordHash;} public String getDisplayName(){return displayName;} public void setDisplayName(String displayName){this.displayName=displayName;} public Instant getCreatedAt(){return createdAt;} }\n";}
 private String generatedUserRepository(String b){return "package "+b+".auth; import java.util.Optional; import java.util.UUID; import org.springframework.data.jpa.repository.JpaRepository; public interface UserRepository extends JpaRepository<User,UUID>{Optional<User> findByEmailIgnoreCase(String email);boolean existsByEmailIgnoreCase(String email);}\n";}
 private String generatedRegisterRequest(String b){return "package "+b+".auth; public record RegisterRequest(String email,String password,String displayName){}\n";}
