 private String generatedAuthResponse(String b){return "package "+b+".auth; public record AuthResponse(String accessToken,String email,String displayName){}\n";}
 private String generatedAuthService(String b){return "package "+b+".auth; import java.util.UUID; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; @Service public class AuthService { private final UserRepository users; private final BCryptPasswordEncoder encoder; public AuthService(UserRepository users,BCryptPasswordEncoder encoder){this.users=users;this.encoder=encoder;} public AuthResponse register(RegisterRequest request){String email=request.email().trim().toLowerCase();if(email.isBlank()||request.password()==null||request.password().length()<8)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,\"Invalid registration\");if(users.existsByEmailIgnoreCase(email))throw new ResponseStatusException(HttpStatus.CONFLICT,\"Email already registered\");User user=new User();user.setEmail(email);user.setPasswordHash(encoder.encode(request.password()));user.setDisplayName(request.displayName().trim());users.save(user);return token(user);} public AuthResponse login(LoginRequest request){User user=users.findByEmailIgnoreCase(request.email().trim()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,\"Invalid credentials\"));if(!encoder.matches(request.password(),user.getPasswordHash()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,\"Invalid credentials\");return token(user);} private AuthResponse token(User user){return new AuthResponse(UUID.randomUUID().toString(),user.getEmail(),user.getDisplayName());}}\n".replace("private final UserRepository users=newPasswordEncoderPlaceholder(); ","private final UserRepository users;");}
 private String generatedAuthController(String b){return "package "+b+".auth; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping(\"/api/auth\") public class AuthController { private final AuthService service; public AuthController(AuthService service){this.service=service;} @PostMapping(\"/register\") @ResponseStatus(HttpStatus.CREATED) public AuthResponse register(@RequestBody RegisterRequest request){return service.register(request);} @PostMapping(\"/login\") public AuthResponse login(@RequestBody LoginRequest request){return service.login(request);} }\n";}
 private String generatedSecurityConfig(String b){return "package "+b+".auth; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.web.SecurityFilterChain; @Configuration public class SecurityConfig { @Bean BCryptPasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain securityFilterChain(HttpSecurity http)throws Exception {http.csrf(csrf->csrf.disable()).authorizeHttpRequests(auth->auth.anyRequest().permitAll());return http.build();} }\n";}
 private String authSchema(){return "CREATE TABLE app_users (\n  id UUID PRIMARY KEY,\n  email VARCHAR(254) NOT NULL UNIQUE,\n  password_hash VARCHAR(100) NOT NULL,\n  display_name VARCHAR(120) NOT NULL,\n  created_at TIMESTAMPTZ NOT NULL\n);\n\n";}

