 private String handler(String b){return "package "+b+".exception;import java.util.Map;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(ResourceNotFoundException.class)ResponseEntity<Map<String,String>> missing(ResourceNotFoundException e){return ResponseEntity.status(404).body(Map.of(\"code\",\"NOT_FOUND\",\"message\",e.getMessage()));}@ExceptionHandler(Exception.class)ResponseEntity<Map<String,String>> unexpected(Exception e){return ResponseEntity.status(500).body(Map.of(\"code\",\"INTERNAL_ERROR\",\"message\",\"Unexpected error\"));}}\n";}
