 private String postman(String artifact,List<Table> tables){Map<String,Object> collection=new LinkedHashMap<>();collection.put("info",Map.of("_postman_id",UUID.nameUUIDFromBytes((artifact+":postman").getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString(),"name",artifact+" API","schema","https://schema.getpostman.com/json/collection/v2.1.0/collection.json"));collection.put("variable",List.of(Map.of("key","baseUrl","value","http://localhost:8080")));List<Object> folders=new ArrayList<>();for(Table table:tables){String resource=table.name().replace('_','-'),idExample=String.valueOf(example(id(table)));String body=tools.jackson.databind.json.JsonMapper.builder().build().writeValueAsString(exampleBody(table));List<Object> requests=new ArrayList<>();requests.add(request("POST "+resource,"POST","{{baseUrl}}/api/"+resource,body));requests.add(request("GET "+resource,"GET","{{baseUrl}}/api/"+resource,null));requests.add(request("GET "+resource+" by id","GET","{{baseUrl}}/api/"+resource+"/"+idExample,null));requests.add(request("PUT "+resource,"PUT","{{baseUrl}}/api/"+resource+"/"+idExample,body));requests.add(request("DELETE "+resource,"DELETE","{{baseUrl}}/api/"+resource+"/"+idExample,null));folders.add(Map.of("name",javaName(table.name()),"item",requests));}collection.put("item",folders);return tools.jackson.databind.json.JsonMapper.builder().build().writerWithDefaultPrettyPrinter().writeValueAsString(collection)+"\n";}
 private Map<String,Object> request(String name,String method,String url,String body){Map<String,Object> request=new LinkedHashMap<>();request.put("method",method);request.put("header",body==null?List.of():List.of(Map.of("key","Content-Type","value","application/json")));request.put("url",Map.of("raw",url,"host",List.of("{{baseUrl}}"),"path",Arrays.stream(url.substring("{{baseUrl}}/".length()).split("/")).toList()));if(body!=null)request.put("body",Map.of("mode","raw","raw",body,"options",Map.of("raw",Map.of("language","json"))));return Map.of("name",name,"request",request,"response",List.of());}
 private Map<String,Object> exampleBody(Table table){Map<String,Object> body=new LinkedHashMap<>();for(Column column:table.columns())body.put(field(column.name()),example(column));return body;}
 private String databaseName(String artifact){String value=artifact.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+","_").replaceAll("^_+|_+$","");if(value.isBlank())value="generated_backend";return value.substring(0,Math.min(value.length(),63));}
 private String developmentPassword(String artifact){String value=UUID.nameUUIDFromBytes(("casegen-generated-dev:"+artifact).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString().replace("-","");return "dev_"+value.substring(0,20);}
 private String markdown(String value){return value==null?"":value.replace('\r',' ').replace('\n',' ').replace('`','\'');}
 private Object example(Column column){String type=column.sqlType().toUpperCase(Locale.ROOT);if(type.startsWith("VARCHAR")||type.equals("TEXT"))return "string";if(type.equals("INTEGER")||type.equals("BIGINT"))return 1;if(type.equals("BOOLEAN"))return true;if(type.startsWith("NUMERIC"))return 1.0;if(type.equals("UUID"))return "00000000-0000-0000-0000-000000000001";return "value";}
 private String contextTest(String b){return "package "+b+";import org.junit.jupiter.api.Test;import org.springframework.boot.test.context.SpringBootTest;@SpringBootTest class ApplicationContextTest{@Test void contextLoads(){}}\n";}
 private void copyWrapper(Path root)throws IOException{Path src=Path.of(System.getProperty("user.dir"));if(!Files.exists(src.resolve("mvnw")))src=src.resolve("backend");for(String f:List.of("mvnw","mvnw.cmd",".mvn/wrapper/maven-wrapper.properties")){Path from=src.resolve(f);if(!Files.exists(from))throw new IOException("Maven Wrapper source missing: "+from);Path to=root.resolve(f);Files.createDirectories(to.getParent());Files.copy(from,to,StandardCopyOption.REPLACE_EXISTING);}}private void put(Path root,String rel,String value)throws IOException{Path p=root.resolve(rel).normalize();if(!p.startsWith(root))throw new IOException("Unsafe generated path");Files.createDirectories(p.getParent());Files.writeString(p,value);}
 private boolean hasCompositeId(Table t){return t.primaryKey()!=null&&t.primaryKey().columns().size()>1;}private String idType(Table t){return hasCompositeId(t)?javaName(t.name())+"Id":javaType(id(t).sqlType());}private Column column(Table t,String name){return t.columns().stream().filter(c->c.name().equals(name)).findFirst().orElseThrow();}private Column id(Table t){return t.columns().stream().filter(c->t.primaryKey().columns().contains(c.name())).findFirst().orElseThrow();}private String javaType(String sql){String s=sql.toUpperCase(Locale.ROOT);if(s.startsWith("VARCHAR")||s.equals("TEXT"))return "String";if(s.equals("INTEGER"))return "Integer";if(s.equals("BIGINT"))return "Long";if(s.equals("BOOLEAN"))return "Boolean";if(s.startsWith("NUMERIC"))return "java.math.BigDecimal";if(s.equals("UUID"))return "java.util.UUID";return "String";}private String javaName(String s){StringBuilder r=new StringBuilder();for(String p:s.split("[-_]"))r.append(cap(p));return r.toString();}private String field(String s){String n=javaName(s);return Character.toLowerCase(n.charAt(0))+n.substring(1);}private String cap(String s){return Character.toUpperCase(s.charAt(0))+s.substring(1);}
 private String columnOptions(String sql){String s=sql.toUpperCase(Locale.ROOT);if(s.startsWith("VARCHAR("))return ",length="+s.substring(8,s.length()-1);if(s.startsWith("NUMERIC(19,2)"))return ",precision=19,scale=2";return "";}
